<body>
<div class="container">
  <h1>🐍 Snake Battle</h1>
  <canvas id="game" width="600" height="600"></canvas>
  <div class="scoreboard">
    <div><div class="label">Player 1 Score</div><div class="value" id="score1">0</div></div>
